def subtract_decorator(constant_value):
    def decorator(func):
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            return result - constant_value
        return wrapper
    return decorator
@subtract_decorator(5)
def add(a, b):
    return a + b
