class Calculator:
    def __init__(self, initial_value):
        self._internal_value = initial_value
    def calculate_difference(self, external_value):
        return self._internal_value - external_value
if __name__ == '__main__':
    my_calc = Calculator(50)
    external_val1 = 20
    result1 = my_calc.calculate_difference(external_val1)
    print(f"Difference 1: {result1}")
    external_val2 = 75
    result2 = my_calc.calculate_difference(external_val2)
    print(f"Difference 2: {result2}")

import unittest
def calculate_difference(a, b):
    return a - b
class TestDifferenceCalculator(unittest.TestCase):
    def test_positive_numbers(self):
        self.assertEqual(calculate_difference(10, 5), 5)
        self.assertEqual(calculate_difference(20, 8), 12)
    def test_negative_numbers(self):
        self.assertEqual(calculate_difference(-10, -5), -5)
        self.assertEqual(calculate_difference(-3, -7), 4)
    def test_mixed_signs(self):
        self.assertEqual(calculate_difference(10, -5), 15)
        self.assertEqual(calculate_difference(-10, 5), -15)
    def test_zero_involvement(self):
        self.assertEqual(calculate_difference(5, 0), 5)
        self.assertEqual(calculate_difference(0, 5), -5)
        self.assertEqual(calculate_difference(0, 0), 0)
    def test_identical_numbers(self):
        self.assertEqual(calculate_difference(7, 7), 0)
        self.assertEqual(calculate_difference(-4, -4), 0)
if __name__ == '__main__':
    unittest.main(argv=['first-arg-is-ignored'], exit=False)

