    print(calculate_difference(10, 3))
    print(calculate_difference(5.5, 2.5))
    try:
        calculate_difference(10, "a")
    except TypeError as e:
        print(f"Error caught: {e}")
    try:
        calculate_difference("hello", 3)
    except TypeError as e:
        print(f"Error caught: {e}")

