    try:
        if not isinstance(num1, (int, float)) or not isinstance(num2, (int, float)):
            raise ValueError("Inputs must be numbers.")
        result = calculate_product(num1, num2)
        print(result)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)

